INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Firewall eine technische Maßnahme zur IT-Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Schützt Netzwerke"}, {"text": "Nein", "correct": false, "because": "Sie ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt eine Firewall?', 3, '[{"text": "Zugriff auf Netzwerke kontrollieren", "correct": true, "because": "Regelt Datenverkehr"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Daten löschen", "correct": false, "because": "Keine Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Firewall filtert Datenverkehr. b) Sie schützt nur vor Viren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Antivirus separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen hat eine Firewall?', 4, '[{"text": "Paketfilterung", "correct": true, "because": "Prüft Datenpakete"}, {"text": "Unklare Filter", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Stateful Inspection", "correct": true, "because": "Verbindungsstatus"}, {"text": "Zugriffssteuerung", "correct": true, "because": "Regelt Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Netzwerk ohne Firewall sicher sein?', 2, '[{"text": "Ja", "correct": true, "because": "Aber riskant"}, {"text": "Nein", "correct": false, "because": "Firewall ergänzt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Firewall im Datenschutz?', 3, '[{"text": "Schützt vor unbefugtem Zugriff", "correct": true, "because": "Kontrolliert Datenverkehr"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Daten löschen", "correct": false, "because": "Keine Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Firewall nur für große Netzwerke relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netze"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat die Paketfilterung in einer Firewall?', 3, '[{"text": "Prüft Datenpakete nach Regeln", "correct": true, "because": "Filtert Verkehr"}, {"text": "Identität prüfen", "correct": false, "because": "Authentifizierung"}, {"text": "Daten speichern", "correct": false, "because": "Andere Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Firewalls können DDoS-Angriffe abwehren. b) Sie sind nur Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Firewall in einem Netzwerk?', 3, '[{"text": "Erhöhtes Risiko unbefugten Zugriffs", "correct": true, "because": "Kein Schutz"}, {"text": "Daten schneller übertragen", "correct": false, "because": "Unsinn"}, {"text": "Netzwerk sicherer", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Firewall ohne Regeln arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Regeln definieren Filter"}, {"text": "Ja", "correct": false, "because": "Funktionslos"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Firewall-Funktion?', 3, '[{"text": "Blockieren von Port 80", "correct": true, "because": "Konkret und real"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk trennen", "correct": false, "because": "Physikalisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Firewall nur für externe Bedrohungen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Netze"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat eine Firewall?', 4, '[{"text": "Filterregeln", "correct": true, "because": "Bestimmt Zugriff"}, {"text": "Unklare Funktion", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Protokollierung", "correct": true, "because": "Zeichnet Verkehr auf"}, {"text": "Portsteuerung", "correct": true, "because": "Regelt Datenfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss eine Firewall konfiguriert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Regeln nötig"}, {"text": "Nein", "correct": false, "because": "Ohne Regeln nutzlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Stateful Inspection?', 3, '[{"text": "Verbindungsstatus überwachen", "correct": true, "because": "Erhöht Sicherheit"}, {"text": "Daten löschen", "correct": false, "because": "Keine Funktion"}, {"text": "Identität prüfen", "correct": false, "because": "Authentifizierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Firewall ohne Protokollierung arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Optional"}, {"text": "Nein", "correct": false, "because": "Protokollierung ergänzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor gefährdet die Wirksamkeit einer Firewall?', 3, '[{"text": "Falsche Konfiguration", "correct": true, "because": "Regeln ineffektiv"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Gute Passwörter", "correct": false, "because": "Unterstützt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Firewalls schützen vor unbefugtem Zugriff. b) Sie sind nur für lokale Netze.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Internet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen einer Firewall?', 3, '[{"text": "Sicherung des Netzwerkverkehrs", "correct": true, "because": "Schützt Daten"}, {"text": "Maximale Offenheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Kontrolle", "correct": false, "because": "Fördert Sicherheit"}]걷');
